INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:bookkeeping:09be779584225d4853e164d92da56066f63e7dac8cb92b98c0eb8571dce3ed3d:bookkeeping:3:unified:payment_deadline_rule:96dd28518995','qualification:bookkeeping',NULL,'bookkeeping:3',NULL,'unified',NULL,2026,'payment_deadline_rule','text'::fact_value_type,'"venue_defined"'::jsonb,'試験日の2ヵ月前を目安に（一部地域で日程が若干異なる場合がございます。詳細は必ず受験希望地の商工会議所にお問合わせください） 、受験希望地の商工会議所に受験申込方法、受験申込書の入手方法、受験料の支払方法等をご確認ください。受験申込受付期間は、商工会議所によって異なります。','試験日の2ヵ月前を目安に（一部地域で日程が若干異なる場合がございます。詳細は必ず受験希望地の商工会議所にお問合わせください） 、受験希望地の商工会議所に受験申込方法、受験申込書の入手方法、受験料の支払方法等をご確認ください。受験申込受付期間は、商工会議所によって異なります。','approved','high'::risk_level,'source:bookkeeping:flow-teller','snapshot:bookkeeping:09be779584225d4853e164d92da56066f63e7dac8cb92b98c0eb8571dce3ed3d',false,'2026-01-01T00:00:00.000Z'::timestamptz);
