INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:fp:c0efa64e9fcb5eac6f14eb0d0b6d512804bd79b17eb67803cd64858290459c1c:jafp:fp:2:academic:cbt:application_deadline_rule','qualification:fp','jafp','fp:2','academic','cbt',NULL,2026,'application_deadline_rule','text'::fact_value_type,'"締切日なし"'::jsonb,'試験日時 休止期間を除き、テストセンターの空いている日時から選択可能です。受検可能な日時はテストセンターにより異なりますので、予約時にご確認ください。休止期間は以下をご確認ください。 試験日程','試験日時 休止期間を除き、テストセンターの空いている日時から選択可能です。受検可能な日時はテストセンターにより異なりますので、予約時にご確認ください。休止期間は以下をご確認ください。 試験日程','approved','high'::risk_level,'source:fp:jafp-2-3-outline','snapshot:fp:c0efa64e9fcb5eac6f14eb0d0b6d512804bd79b17eb67803cd64858290459c1c',false,'2026-01-01T00:00:00.000Z'::timestamptz);
INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:fp:c0efa64e9fcb5eac6f14eb0d0b6d512804bd79b17eb67803cd64858290459c1c:jafp:fp:2:academic:cbt:application_open_rule','qualification:fp','jafp','fp:2','academic','cbt',NULL,2026,'application_open_rule','text'::fact_value_type,'"随時"'::jsonb,'学科試験及び実技試験とも、全国で随時受検ができるCBT（Computer Based Testing）試験へ完全移行し、運営を株式会社シー・ビー・ティ・ソリューションズ（以下、「CBTソリューションズ」）に委託します。','学科試験及び実技試験とも、全国で随時受検ができるCBT（Computer Based Testing）試験へ完全移行し、運営を株式会社シー・ビー・ティ・ソリューションズ（以下、「CBTソリューションズ」）に委託します。','approved','high'::risk_level,'source:fp:jafp-2-3-outline','snapshot:fp:c0efa64e9fcb5eac6f14eb0d0b6d512804bd79b17eb67803cd64858290459c1c',false,'2026-01-01T00:00:00.000Z'::timestamptz);
INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:fp:c0efa64e9fcb5eac6f14eb0d0b6d512804bd79b17eb67803cd64858290459c1c:jafp:fp:2:academic:cbt:eligibility','qualification:fp','jafp','fp:2','academic','cbt',NULL,2026,'eligibility','text'::fact_value_type,'"1） 3級FP技能検定の合格者 受検申請時に、合格番号を入力してください。 / 2） 受検申請時点で、FP業務に関し2年以上の実務経験を有する者 受検申請時に、勤務先名、経験年月を入力してください。 / 3） 受検申請時点で、日本FP協会認定のAFP認定研修を修了している者（修了証明書の保持者） 受検申請時に、AFP認定研修の受講者番号を入力してください。修了の時期により、修了証明書の画像をアップロードいただく場合があります。予約画面の指示に従ってください。 / 4） 金融渉外技能審査3級（旧審査試験）の合格者 日本FP協会へお問合せください。"'::jsonb,'1） 3級FP技能検定の合格者 受検申請時に、合格番号を入力してください。 / 2） 受検申請時点で、FP業務に関し2年以上の実務経験を有する者 受検申請時に、勤務先名、経験年月を入力してください。 / 3） 受検申請時点で、日本FP協会認定のAFP認定研修を修了している者（修了証明書の保持者） 受検申請時に、AFP認定研修の受講者番号を入力してください。修了の時期により、修了証明書の画像をアップロードいただく場合があります。予約画面の指示に従ってください。 / 4） 金融渉外技能審査3級（旧審査試験）の合格者 日本FP協会へお問合せください。','1） 3級FP技能検定の合格者 受検申請時に、合格番号を入力してください。 / 2） 受検申請時点で、FP業務に関し2年以上の実務経験を有する者 受検申請時に、勤務先名、経験年月を入力してください。 / 3） 受検申請時点で、日本FP協会認定のAFP認定研修を修了している者（修了証明書の保持者） 受検申請時に、AFP認定研修の受講者番号を入力してください。修了の時期により、修了証明書の画像をアップロードいただく場合があります。予約画面の指示に従ってください。 / 4） 金融渉外技能審査3級（旧審査試験）の合格者 日本FP協会へお問合せください。','approved','high'::risk_level,'source:fp:jafp-2-3-outline','snapshot:fp:c0efa64e9fcb5eac6f14eb0d0b6d512804bd79b17eb67803cd64858290459c1c',false,'2026-01-01T00:00:00.000Z'::timestamptz);
