INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:fp:8a77e714535cf411a4acc6fa4faa7f87593bef5feee5d54b0c4ad298f6e803cf:kinzai:fp:1:practical:asset-consulting:interview:exam_method','qualification:fp','kinzai','fp:1','practical:asset-consulting','interview',NULL,2026,'exam_method','text'::fact_value_type,'"interview"'::jsonb,'対面の口述試験','面接は、異なる設例課題に基づき、2回行います。 いずれの面接も、「設例課題」に基づいて、複数の審査委員と対面の口述試験を行います。 審査は、関連業法との関係及び職業上の倫理を踏まえたファイナンシャル・プランニング、顧客のニーズ及び問題点の把握、問題解決策の検討・分析、顧客の立場に立った対応といった観点から行われます。 配点は、1回目・2回目とも各100点の200点満点で、合計120点以上が合格となります。 「設例課題」は、それぞれ面接開始の約15分前に渡されます。各面接の1人当たりの所要時間は約12分です。 設例課題の検討にあたっては、とくに指示のない限り、試験日現在施行の法令等に基づいてください。','approved','high'::risk_level,'source:fp:kinzai-1-practical','snapshot:fp:8a77e714535cf411a4acc6fa4faa7f87593bef5feee5d54b0c4ad298f6e803cf',false,'2026-01-01T00:00:00.000Z'::timestamptz);
