INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd:passing_standard','qualification:gyoseishoshi',NULL,NULL,NULL,NULL,NULL,2026,'passing_standard','text'::fact_value_type,'"法令等50%以上・基礎知識40%以上・全体60%以上"'::jsonb,'次の要件のいずれも満たした者を合格とします。 ① 行政書士の業務に関し必要な法令等科目の得点が、満点の５０パーセント以上である者 ② 行政書士の業務に関し必要な基礎知識科目の得点が、満点の４０パーセント以上である者 ③ 試験全体の得点が、満点の６０パーセント以上である者','次の要件のいずれも満たした者を合格とします。 ① 行政書士の業務に関し必要な法令等科目の得点が、満点の５０パーセント以上である者 ② 行政書士の業務に関し必要な基礎知識科目の得点が、満点の４０パーセント以上である者 ③ 試験全体の得点が、満点の６０パーセント以上である者','approved','high'::risk_level,'source:gyoseishoshi:guide','snapshot:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd',false,'2026-01-01T00:00:00.000Z'::timestamptz);
INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd:payment_deadline_rule','qualification:gyoseishoshi',NULL,NULL,NULL,NULL,NULL,2026,'payment_deadline_rule','text'::fact_value_type,'"申込受付期間内"'::jsonb,'受験手数料は、受験願書の受付期間内に払い込んでください。 受験願書は、受付締切日までの消印があり、かつ、この日までの受付郵便局の日附印がある｢振替払込受付証明書（お客さま用）｣が貼られている不備のないものを受け付けます。','受験手数料は、受験願書の受付期間内に払い込んでください。 受験願書は、受付締切日までの消印があり、かつ、この日までの受付郵便局の日附印がある｢振替払込受付証明書（お客さま用）｣が貼られている不備のないものを受け付けます。','approved','high'::risk_level,'source:gyoseishoshi:guide','snapshot:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd',false,'2026-01-01T00:00:00.000Z'::timestamptz);
INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd:question_count','qualification:gyoseishoshi',NULL,NULL,NULL,NULL,NULL,2026,'question_count','integer'::fact_value_type,'"60"'::jsonb,'行政書士の業務に関し必要な法令等（出題数４６題） 憲法、行政法（行政法の一般的な法理論、行政手続法、行政不服審査法、行政事件訴訟法、国家賠償法及び地方自治法を中心とする。）、民法、商法及び基礎法学の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。 / 行政書士の業務に関し必要な基礎知識（出題数１４題） 一般知識、行政書士法等行政書士業務と密接に関連する諸法令、情報通信・個人情報保護及び文章理解の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。','行政書士の業務に関し必要な法令等（出題数４６題） 憲法、行政法（行政法の一般的な法理論、行政手続法、行政不服審査法、行政事件訴訟法、国家賠償法及び地方自治法を中心とする。）、民法、商法及び基礎法学の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。 / 行政書士の業務に関し必要な基礎知識（出題数１４題） 一般知識、行政書士法等行政書士業務と密接に関連する諸法令、情報通信・個人情報保護及び文章理解の中からそれぞれ出題し、法令については、令和８年４月１日現在施行されている法令に関して出題します。','approved','high'::risk_level,'source:gyoseishoshi:guide','snapshot:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd',false,'2026-01-01T00:00:00.000Z'::timestamptz);
INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd:question_format','qualification:gyoseishoshi',NULL,NULL,NULL,NULL,NULL,2026,'question_format','text'::fact_value_type,'"択一式・記述式"'::jsonb,'出題の形式は、「行政書士の業務に関し必要な法令等」は択一式及び記述式とし、「行政書士の業務に関し必要な基礎知識」は択一式とします。 記述式は、４０字程度で記述するものを出題します。','出題の形式は、「行政書士の業務に関し必要な法令等」は択一式及び記述式とし、「行政書士の業務に関し必要な基礎知識」は択一式とします。 記述式は、４０字程度で記述するものを出題します。','approved','high'::risk_level,'source:gyoseishoshi:guide','snapshot:gyoseishoshi:e634d0296d1ded3352a3684c352114f0a24d25a7a10c167a32f8028d1d600ecd',false,'2026-01-01T00:00:00.000Z'::timestamptz);
