INSERT INTO candidate_facts (id,qualification_id,provider_id,exam_level_id,exam_component,delivery_mode,payment_method,exam_year,fact_key,value_type,normalized_value,display_value,evidence_text,status,risk_level,source_id,source_snapshot_id,synthetic,created_at) VALUES ('candidate:takken:e1f623471480570afcd985e584734cb28f85615966bd170d5eb65abc41501f11:exam_subjects','qualification:takken',NULL,NULL,NULL,NULL,NULL,2026,'exam_subjects','text'::fact_value_type,'"土地の形質、地積、地目及び種別並びに建物の形質、構造及び種別、土地及び建物についての権利及び権利の変動に関する法令、土地及び建物についての法令上の制限、宅地及び建物についての税に関する法令、宅地及び建物の需給に関する法令及び実務、宅地及び建物の価格の評定、宅地建物取引業法及び同法の関係法令"'::jsonb,'土地の形質、地積、地目及び種別並びに建物の形質、構造及び種別、土地及び建物についての権利及び権利の変動に関する法令、土地及び建物についての法令上の制限、宅地及び建物についての税に関する法令、宅地及び建物の需給に関する法令及び実務、宅地及び建物の価格の評定、宅地建物取引業法及び同法の関係法令','試験の内容は、おおむね次のとおりです。土地の形質、地積、地目及び種別並びに建物の形質、構造及び種別に関すること。土地及び建物についての権利及び権利の変動に関する法令に関すること。土地及び建物についての法令上の制限に関すること。宅地及び建物についての税に関する法令に関すること。宅地及び建物の需給に関する法令及び実務に関すること。宅地及び建物の価格の評定に関すること。宅地建物取引業法及び同法の関係法令に関すること。','approved','high'::risk_level,'source:takken:retio-exam','snapshot:takken:e1f623471480570afcd985e584734cb28f85615966bd170d5eb65abc41501f11',false,'2026-01-01T00:00:00.000Z'::timestamptz);
